// 1. Towering Mountain Peaks
function createMountainPeak(x, y, z, radius, height, rockColor, hasSnowCap, id, name) {
  const peakGroup = new THREE.Group();
  peakGroup.position.set(x, y, z);

  // Main rock body with faceted low-poly alpine finish
  const bodyGeo = new THREE.ConeGeometry(radius, height, 7, 3);
  const bodyMat = new THREE.MeshStandardMaterial({
    color: rockColor,
    roughness: 0.94,
    metalness: 0.05,
    flatShading: true,
  });
  const bodyMesh = new THREE.Mesh(bodyGeo, bodyMat);
  bodyMesh.position.y = height / 2;
  bodyMesh.castShadow = true;
  bodyMesh.receiveShadow = true;
  peakGroup.add(bodyMesh);

  // Snow cap on top 35% of peak if specified
  if (hasSnowCap) {
    const capHeight = height * 0.35;
    const capRadius = radius * 0.38;
    const capGeo = new THREE.ConeGeometry(capRadius, capHeight, 7, 1);
    const capMat = new THREE.MeshStandardMaterial({
      color: 0xf1f5f9,
      roughness: 0.6,
      metalness: 0.02,
      flatShading: true,
    });
    const capMesh = new THREE.Mesh(capGeo, capMat);
    capMesh.position.y = height - capHeight / 2 + 0.1;
    capMesh.castShadow = true;
    peakGroup.add(capMesh);
  }

  peakGroup.userData = { id, name, type: 'geology', collidable: true };
  scene.add(peakGroup);
  return peakGroup;
}

